import unittest
import cron_hour as app

class Behavior(unittest.TestCase):
    def test_ranges(self):
        for field,want in [('*/23',[0,23]),('*/7',[0,7,14,21]),('1-9/3',[1,4,7]),('8-11',[8,9,10,11]),('5-5/2',[5]),('3-8/20',[3]),('0-23/2',list(range(0,24,2))),('*',list(range(24)))]:
            self.assertEqual(app.expand_hours(field),want)


if __name__ == "__main__":
    unittest.main()

